<?php
require_once 'includes/config.php'; require_admin(); require_once 'includes/export_pdf.php';
$name=trim($_GET['name']??''); $class=(int)($_GET['class']??0); $gender=trim($_GET['gender']??''); $format=$_GET['format']??'csv';
$sql="SELECT s.StudentId,s.StudentName,s.RollId,s.StudentEmail,s.Gender,s.DOB,s.NextOfKinName,s.NextOfKinPhone,s.Status,c.ClassName,c.Section FROM tblstudents s LEFT JOIN tblclasses c ON c.id=s.ClassId WHERE 1=1";$p=[];if($name!==''){$sql.=" AND s.StudentName LIKE :name";$p[':name']="%$name%";}if($class){$sql.=" AND s.ClassId=:class";$p[':class']=$class;}if($gender!==''){$sql.=" AND s.Gender=:gender";$p[':gender']=$gender;}$sql.=" ORDER BY s.StudentName";$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
if($format==='pdf'){srms_pdf_download('students-export.pdf','Registered Students',[['key'=>'StudentName','label'=>'Student','width'=>135],['key'=>'RollId','label'=>'Roll ID','width'=>70],['key'=>'Class','label'=>'Class','width'=>100],['key'=>'Gender','label'=>'Gender','width'=>60],['key'=>'StudentEmail','label'=>'Email','width'=>150],['key'=>'NextOfKinName','label'=>'Next of Kin','width'=>120],['key'=>'NextOfKinPhone','label'=>'NOK Phone','width'=>100]],array_map(function($r){$r['Class']=$r['ClassName'].' - '.$r['Section'];return $r;},$rows));}
header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="students-export.csv"');$out=fopen('php://output','w');fputcsv($out,['Student','Roll ID','Email','Gender','DOB','Class','Next of Kin Name','Next of Kin Phone','Status']);foreach($rows as $r)fputcsv($out,[$r['StudentName'],$r['RollId'],$r['StudentEmail'],$r['Gender'],$r['DOB'],$r['ClassName'].' - '.$r['Section'],$r['NextOfKinName'],$r['NextOfKinPhone'],$r['Status']?'Active':'Blocked']);exit;
